using System.Globalization;
using System.Reflection;
using System.Text;

namespace Moonwell.Build
{
    /// <summary>
    /// The stubs CSharp.lua compiles in place of the generated classes of <c>Moonwell.Objects</c>, which it does not read (each
    /// generated file is inside <c>#if !MOONWELL_LUA</c>): the classes the map uses, each with only the members the map's assembly
    /// names. Compiling thousands of ignored classes cost CSharp.lua about ten seconds a build (findings.md). The choice enums the
    /// map names and <c>[BeyondLimits]</c> are stubbed with them (<see cref="Support"/>): their own files are inside
    /// <c>#if !MOONWELL_LUA</c> too, since CSharp.lua writes an empty namespace into the script for each file, and a blank line
    /// for each type after the first of a namespace.
    /// </summary>
    public static class ObjectStubs
    {
        /// <summary>The file's name in the project's generated folder, which CSharp.lua compiles and <c>dotnet build</c> leaves out.</summary>
        public const string FileName = "ObjectStubs.g.cs";

        private const string ObjectsNamespace = "Moonwell.Objects";

        private const BindingFlags DeclaredMembers =
            BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;

        /// <summary>Writes the stubs of the used classes of <c>Moonwell.Objects</c> into the project's generated folder.</summary>
        /// <param name="project">The map project.</param>
        /// <param name="used">The used classes.</param>
        /// <param name="support">The stubs of the enums and the attribute (<see cref="Support"/>), written in the first namespace block.</param>
        /// <returns>The path of the file written.</returns>
        public static string Write(MapProject project, IReadOnlyList<UsedClass> used, string support)
        {
            var text = new StringBuilder();
            text.Append("// Generated by Moonwell's build. Do not edit; every build writes it anew.\n");
            text.Append("// The classes of Moonwell.Objects the map uses, with the members its assembly names: CSharp.lua compiles these in place of the library's.\n");
            text.Append("#nullable disable\n");
            // A standard class is nested in the classes of its group and kind (Moonwell.Objects.Human.Units.Paladin); a kind base is not.
            // The support goes into the first block: a block of its own would be one more empty namespace in the map's script.
            var groups = used.Where(one => one.InObjects).GroupBy(one => NamespaceOf(one.FullName)).OrderBy(group => group.Key, StringComparer.Ordinal).ToList();
            if (groups.Count == 0 && support.Length > 0)
            {
                text.Append("\nnamespace ").Append(ObjectsNamespace).Append("\n{\n").Append(support).Append("}\n");
            }

            foreach (var group in groups)
            {
                var containers = group.Key.Length > ObjectsNamespace.Length
                    ? group.Key.Substring(ObjectsNamespace.Length + 1).Split('.')
                    : Array.Empty<string>();
                text.Append("\nnamespace ").Append(ObjectsNamespace).Append("\n{\n");
                if (group == groups[0] && support.Length > 0)
                {
                    text.Append(support).Append('\n');
                }

                for (var c = 0; c < containers.Length; c++)
                {
                    var at = new string(' ', 4 * (c + 1));
                    text.Append(at).Append("/// @CSharpLua.Ignore\n").Append(at).Append("public static partial class ").Append(containers[c]).Append('\n').Append(at).Append("{\n");
                }

                var indent = new string(' ', 4 * containers.Length);
                var separator = string.Empty;
                foreach (var one in group)
                {
                    text.Append(separator).Append(Indent(one.Stub, indent));
                    separator = "\n";
                }

                for (var c = containers.Length - 1; c >= 0; c--)
                {
                    text.Append(new string(' ', 4 * (c + 1))).Append("}\n");
                }

                text.Append("}\n");
            }

            Directory.CreateDirectory(project.GeneratedFolder);
            var path = Path.Combine(project.GeneratedFolder, FileName);
            File.WriteAllText(path, text.ToString());
            return path;
        }

        /// <summary>
        /// The stubs of what the map's code names in <c>Moonwell.Objects</c> besides the classes: the choice enums, with their members'
        /// numbers (CSharp.lua writes a member as its number), and <c>BeyondLimitsAttribute</c>. Each is <c>@CSharpLua.Ignore</c>.
        /// </summary>
        /// <param name="enums">The enums the map's assembly names or a stub's members have in their signatures.</param>
        /// <param name="beyondLimits">Whether the map's assembly names <c>BeyondLimitsAttribute</c>.</param>
        /// <returns>The declarations, indented for a namespace block; empty when there are none.</returns>
        internal static string Support(IEnumerable<Type> enums, bool beyondLimits)
        {
            var text = new StringBuilder();
            foreach (var type in enums.OrderBy(type => type.Name, StringComparer.Ordinal))
            {
                text.Append("    /// @CSharpLua.Ignore\n");
                if (type.GetCustomAttributesData().Any(attribute => attribute.AttributeType.FullName == "System.FlagsAttribute"))
                {
                    text.Append("    [global::System.Flags]\n");
                }

                text.Append("    public enum ").Append(type.Name).Append("\n    {\n");
                foreach (var field in type.GetFields(BindingFlags.Public | BindingFlags.Static))
                {
                    var number = Convert.ToInt64(field.GetRawConstantValue(), CultureInfo.InvariantCulture);
                    text.Append("        ").Append(field.Name).Append(" = ").Append(number.ToString(CultureInfo.InvariantCulture)).Append(",\n");
                }

                text.Append("    }\n\n");
            }

            if (beyondLimits)
            {
                text.Append("    /// @CSharpLua.Ignore\n");
                text.Append("    [global::System.AttributeUsage(global::System.AttributeTargets.Class, AllowMultiple = true, Inherited = true)]\n");
                text.Append("    public sealed class BeyondLimitsAttribute : global::System.Attribute\n    {\n");
                text.Append("        public BeyondLimitsAttribute(params string[] properties) { }\n    }\n");
            }

            return text.ToString();
        }

        /// <summary>Deletes the stubs an earlier build left: without <c>Moonwell.Objects</c> they would not compile.</summary>
        /// <param name="project">The map project.</param>
        public static void Delete(MapProject project)
        {
            var path = Path.Combine(project.GeneratedFolder, FileName);
            if (File.Exists(path))
            {
                File.Delete(path);
            }
        }

        /// <summary>
        /// The stub of a class of <c>Moonwell.Objects</c>: marked <c>@CSharpLua.Ignore</c>, with its base and the members it declares whose
        /// names are given, in its order, with empty bodies. A property keeps its accessors (CSharp.lua calls <c>getName</c> and
        /// <c>setName</c> only for a property with bodies), and a name brings every overload, since CSharp.lua names overloads by their order.
        /// </summary>
        /// <param name="type">The class, loaded in the build's load context.</param>
        /// <param name="names">The names of the members to keep; a property by its own name.</param>
        /// <returns>The class's C#, indented for a namespace block.</returns>
        internal static string Class(Type type, IReadOnlySet<string> names)
        {
            var text = new StringBuilder();
            text.Append("    /// @CSharpLua.Ignore\n");
            text.Append("    public ").Append(type.IsAbstract ? "abstract " : string.Empty).Append("class ").Append(type.Name)
                .Append(" : ").Append(TypeName(type.BaseType!)).Append("\n    {\n");
            var separator = string.Empty;
            foreach (var member in type.GetMembers(DeclaredMembers).Where(member => names.Contains(member.Name)).OrderBy(member => member.MetadataToken))
            {
                if (member is PropertyInfo property)
                {
                    text.Append(separator);
                    WriteProperty(text, property);
                    separator = "\n";
                }
                else if (member is MethodInfo method && !method.IsSpecialName)
                {
                    text.Append(separator);
                    WriteMethod(text, method);
                    separator = "\n";
                }
            }

            text.Append("    }\n");
            return text.ToString();
        }

        /// <summary>Adds the enums of <c>Moonwell.Objects</c> in the signatures of the members of a class that <see cref="Class"/> keeps.</summary>
        /// <param name="type">The class, loaded in the build's load context.</param>
        /// <param name="names">The names of the members to keep.</param>
        /// <param name="enums">The enums found so far.</param>
        internal static void AddEnums(Type type, IReadOnlySet<string> names, ISet<Type> enums)
        {
            foreach (var member in type.GetMembers(DeclaredMembers).Where(member => names.Contains(member.Name)))
            {
                if (member is PropertyInfo property)
                {
                    AddEnums(property.PropertyType, enums);
                }
                else if (member is MethodInfo method && !method.IsSpecialName)
                {
                    AddEnums(method.ReturnType, enums);
                    foreach (var parameter in method.GetParameters())
                    {
                        AddEnums(parameter.ParameterType, enums);
                    }
                }
            }
        }

        /// <summary>Adds a type, when it is an enum of <c>Moonwell.Objects</c>, and the enums among its generic arguments or its elements.</summary>
        /// <param name="type">The type.</param>
        /// <param name="enums">The enums found so far.</param>
        internal static void AddEnums(Type type, ISet<Type> enums)
        {
            if (type.IsArray)
            {
                AddEnums(type.GetElementType()!, enums);
            }
            else if (type.IsEnum && type.IsPublic && type.Namespace == ObjectsNamespace)
            {
                enums.Add(type);
            }
            else if (type.IsGenericType)
            {
                foreach (var argument in type.GetGenericArguments())
                {
                    AddEnums(argument, enums);
                }
            }
        }

        /// <summary>The methods a class declares whose names are given, in its order, with the names CSharp.lua gives them.</summary>
        /// <param name="type">The class, loaded in the build's load context.</param>
        /// <param name="names">The names of the methods to keep.</param>
        /// <returns>The methods.</returns>
        internal static IReadOnlyList<UsedMethod> Methods(Type type, IReadOnlySet<string> names)
        {
            var methods = new List<UsedMethod>();
            var overloads = new Dictionary<string, int>(StringComparer.Ordinal);
            foreach (var method in type.GetMethods(DeclaredMembers).Where(method => !method.IsSpecialName && names.Contains(method.Name)).OrderBy(method => method.MetadataToken))
            {
                var count = overloads.GetValueOrDefault(method.Name);
                overloads[method.Name] = count + 1;
                methods.Add(new UsedMethod(count == 0 ? method.Name : method.Name + count, method.ReturnType.FullName == "System.Void"));
            }

            return methods;
        }

        private static void WriteProperty(StringBuilder text, PropertyInfo property)
        {
            var getter = property.GetGetMethod(true);
            var setter = property.GetSetMethod(true);
            var first = (getter ?? setter)!;
            var access = Access(first);
            text.Append("        ").Append(access).Append(first.IsStatic ? " static " : " ").Append(TypeName(property.PropertyType)).Append(' ')
                .Append(property.Name).Append("\n        {\n");
            if (getter != null)
            {
                text.Append("            ").Append(Access(getter) == access ? string.Empty : Access(getter) + " ").Append("get { return default; }\n");
            }

            if (setter != null)
            {
                text.Append("            ").Append(Access(setter) == access ? string.Empty : Access(setter) + " ").Append("set { }\n");
            }

            text.Append("        }\n");
        }

        private static void WriteMethod(StringBuilder text, MethodInfo method)
        {
            text.Append("        ").Append(Access(method)).Append(method.IsStatic ? " static " : " ").Append(TypeName(method.ReturnType)).Append(' ').Append(method.Name);
            if (method.IsGenericMethodDefinition)
            {
                text.Append('<').Append(string.Join(", ", method.GetGenericArguments().Select(argument => argument.Name))).Append('>');
            }

            var parameters = method.GetParameters().Select(parameter =>
            {
                var many = parameter.GetCustomAttributesData().Any(attribute => attribute.AttributeType.FullName == "System.ParamArrayAttribute");
                return (many ? "params " : string.Empty) + TypeName(parameter.ParameterType) + " " + parameter.Name;
            });
            text.Append('(').Append(string.Join(", ", parameters)).Append(')');
            text.Append(method.ReturnType.FullName == "System.Void" ? " { }\n" : " { return default; }\n");
        }

        private static string Access(MethodInfo method)
        {
            if (method.IsPublic)
            {
                return "public";
            }

            if (method.IsFamilyOrAssembly)
            {
                return "protected internal";
            }

            if (method.IsFamily)
            {
                return "protected";
            }

            if (method.IsAssembly)
            {
                return "internal";
            }

            return method.IsFamilyAndAssembly ? "private protected" : "private";
        }

        // A type as C# names it from anywhere: keywords for the simple types, global:: for the others.
        private static string TypeName(Type type)
        {
            if (type.IsGenericParameter)
            {
                return type.Name;
            }

            if (type.IsArray)
            {
                return TypeName(type.GetElementType()!) + "[]";
            }

            if (type.Namespace == "System" && !type.IsGenericType)
            {
                switch (type.Name)
                {
                    case "Void":
                        return "void";
                    case "String":
                        return "string";
                    case "Int32":
                        return "int";
                    case "Single":
                        return "float";
                    case "Boolean":
                        return "bool";
                    case "Object":
                        return "object";
                }
            }

            var name = type.Name;
            var tick = name.IndexOf('`');
            if (tick >= 0)
            {
                name = name.Substring(0, tick);
            }

            var outer = type.IsNested ? TypeName(type.DeclaringType!) : "global::" + (string.IsNullOrEmpty(type.Namespace) ? string.Empty : type.Namespace);
            var text = outer.EndsWith("::", StringComparison.Ordinal) ? outer + name : outer + "." + name;
            if (type.IsGenericType)
            {
                text += "<" + string.Join(", ", type.GetGenericArguments().Select(TypeName)) + ">";
            }

            return text;
        }

        private static string Indent(string text, string indent)
        {
            if (indent.Length == 0)
            {
                return text;
            }

            var lines = text.Split('\n');
            for (var i = 0; i < lines.Length; i++)
            {
                if (lines[i].Length > 0)
                {
                    lines[i] = indent + lines[i];
                }
            }

            return string.Join('\n', lines);
        }

        private static string NamespaceOf(string fullName)
        {
            var dot = fullName.LastIndexOf('.');
            return dot < 0 ? string.Empty : fullName.Substring(0, dot);
        }
    }
}
